import{z as m,x as p,o as t,c as A,q as s,j as E,D as e,d as n,s as r,S as l,b as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"组合计数","description":"","frontmatter":{"title":"组合计数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/counting-combinatorics.md","filePath":"cs/counting-combinatorics.md","lastUpdated":1791413859000}'),c={name:"cs/counting-combinatorics.md"};function d(B,a,b,h,k,D){const o=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=s('<h1 id="组合计数" tabindex="-1">组合计数 <a class="header-anchor" href="#组合计数" aria-label="Permalink to &quot;组合计数&quot;">​</a></h1><div class="epigraph"><p>先分清有序还是无序、是否放回，再套乘法原理；阶乘与二项式只是这几条规则的缩写。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications 整理</footer></div><p>上一课<a href="/cs/tree-as-acyclic">树作为无环连通图</a>钉死了树的等价定义。本课不重证 \\(|E|=|V|-1\\)，也不从「概率」另起。缺口是：后课概率要把「有多少种」当测度的底；渐近有时也要数操作次数。图和树给出对象，还没有系统的<strong>计数</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>树的个数、比特串的个数、从 \\(n\\) 个寄存器里选 \\(k\\) 个，若每次重新发明，后课离散概率没有 \\(p=\\#A/\\#\\Omega\\)。缺口因此不是新的图类，而是乘法原理、加法原理（划分）、排列 \\(P(n,k)=n!/(n-k)!\\)、组合 \\(C(n,k)=\\binom{n}{k}\\)、二项式定理。有限 \\(\\Sigma^n\\) 的 \\(2^n\\) 在<a href="/cs/bit-as-distinction">第一课</a>已出现，现在要能数「恰有 \\(k\\) 个 1」的串：\\(\\binom{n}{k}\\)。</p><p>容斥、生成函数点到为止：本课够用的是不放回选取与二项式，不把 Catalan 当主干定理。</p><h3 id="排列不是「随便排一下」" tabindex="-1">排列不是「随便排一下」 <a class="header-anchor" href="#排列不是「随便排一下」" aria-label="Permalink to &quot;排列不是「随便排一下」&quot;">​</a></h3><p>有序：\\(n\\) 个座位的函数注入。无序：只关心子集。比特上「有 3 个 1」是组合；指令立即数的位型是排列还是组合，取决于是否区分顺序。把 \\(\\binom{n}{k}\\) 当成 \\(n^k\\)，哈希槽估计会错一个阶。</p><p><span class="marginnote">Rosen 用鸽笼与计数夹在一起。本课计数为主；鸽笼在可数课已有。Cayley \\(n^{n-2}\\) 棵标号树只作例，不证。</span></p><p><span class="marginnote">数字实例：从 50 人班里选 3 人当代表（无序）是 \\(\\binom{50}{3}=19600\\) 种；选 3 人分别当主席、文书、财务（有序）是 \\(50\\times49\\times48=117600\\) 种——恰好差 \\(3!=6\\) 倍，因为同一组 3 人有 6 种排座次的方式。有序与否，答案差的就是这种「组内排列数」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分步计数则相乘，分类划分则相加。\\(\\binom{n}{k}=\\binom{n}{n-k}\\)，\\(\\binom{n}{k}=\\binom{n-1}{k}+\\binom{n-1}{k-1}\\)——后者是归纳与后课动态规划的原型，本课只当恒等式。</p>',12)),(t(),E(l,null,{default:e(()=>[r(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E6%9C%89%E9%99%90%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20MUL%5B%22%E5%88%86%E6%AD%A5%E7%9B%B8%E4%B9%98%22%5D%0A%20%20OBJ%20--%3E%20ADD%5B%22%E5%88%92%E5%88%86%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20MUL%20--%3E%20BIN%5B%22%E6%8E%92%E5%88%97%E4%B8%8E%E7%BB%84%E5%90%88%22%5D%0A%20%20BIN%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%9D%87%E5%8C%80%E6%A6%82%E7%8E%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[n("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,[n("均匀概率的样本空间大小由本课给出。后课哈希的「生日」用 \\(\\binom{n}{2}\\) 对。纠错码的球体积 \\(\\sum_{i=0}^{t}\\binom{n}{i}\\) 是汉明界的组合部分，"),i("a",{href:"/cs/error-correcting-intuition"},"纠错课"),n("只谈了距离，计数在这里补上，不重写译码。")],-1)),(t(),E(l,null,{default:e(()=>[r(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A6%81%E6%95%B0%E5%A4%9A%E5%B0%91%E4%B8%AA%E6%96%B9%E6%A1%88%22%5D%20--%3E%20R%7B%22%E5%85%81%E8%AE%B8%E9%87%8D%E5%A4%8D%E9%80%89%E5%8F%96%3F%22%7D%0A%20%20R%20--%20%22%E4%B8%8D%E8%AE%B8%E9%87%8D%E5%A4%8D%22%20--%3E%20O%7B%22%E9%A1%BA%E5%BA%8F%E8%A6%81%E7%B4%A7%3F%22%7D%0A%20%20O%20--%20%22%E8%A6%81%E7%B4%A7%22%20--%3E%20P%5B%22%E6%8E%92%E5%88%97%20n!%20%E9%99%A4%E4%BB%A5%20n-k%20%E7%9A%84%E9%98%B6%E4%B9%98%22%5D%0A%20%20O%20--%20%22%E4%B8%8D%E8%A6%81%E7%B4%A7%22%20--%3E%20C%5B%22%E7%BB%84%E5%90%88%20n%20%E9%80%89%20k%22%5D%0A%20%20R%20--%20%22%E5%85%81%E8%AE%B8%E9%87%8D%E5%A4%8D%22%20--%3E%20M%5B%22%E6%AF%8F%E6%AD%A5%20n%20%E7%A7%8D%E8%BF%9E%E4%B9%98%E5%8D%B3%20n%20%E7%9A%84%20k%20%E6%AC%A1%E6%96%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">这张图回答「一道计数题该套哪条公式」：先问能不能重复选，再问顺序要不要紧，两问答完公式就定了。多数数错的题都是这两问没分清，而不是公式记错。</span></p><p>树上：有根有序二叉树的个数满足 Catalan 递推，本课承认递推可用归纳验证，不把封闭形式当必考。</p><p><span class="marginnote">直觉类比：\\(\\binom{n}{k}=\\binom{n}{n-k}\\) 可以想象成「选上的人」和「留下的人」一一对应——从 50 人里挑 3 个进队，等价于挑 47 个不进队，两种数法必然给出同一个数。</span></p><p><span class="marginnote">常见误区：把 \\(\\binom{n}{k}\\) 与 \\(n^k\\) 混为一谈。\\(n^k\\) 是「每个位置独立任选、可重复」，\\(\\binom{n}{k}\\) 是「不许重复的无序子集」，两者常差几个数量级；数「多少对」要用 \\(\\binom{n}{2}=n(n-1)/2\\)，而不是 \\(n^2\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Stirling 第二类数的全部表，不把无限生成函数当分析课。也不把连续组合（体积）请进来：对象仍有限。</p><p>后课默认：数有限结构先问有序与否；均匀随机的分母来自本课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>乘法原理管分步，二项式管无序选取。</li><li>\\(\\binom{n}{k}\\) 计恰 \\(k\\) 个 1 的比特串；排列管有序注入。</li><li>计数给下一课均匀概率提供 \\(|\\Omega|\\)。</li><li>出处：Rosen, <em>Discrete Mathematics</em>。</li></ul>',9))])}const f=m(c,[["render",d]]);export{_ as __pageData,f as default};
